package boundary

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// The fixtures are generated by the TypeScript library (test/gen-fixtures.ts).
// Both implementations must agree byte for byte on every block they write
// and on every verdict they give.

type fixtures struct {
	Wrap []struct {
		Name, Input, Source, Text, Hash, Content string
		Disarmed, Invisible                      int
	}
	Verify []struct {
		Name, Text string
		OK         bool `json:"ok"`
		Blocks     []struct {
			Kind       string
			Hash       string
			Start, End int
		}
		Problems []Problem
	}
	Upgrade []struct {
		Name, Text string
		Result     *struct {
			Vendor, Description, Inner string
		}
	}
	Scrub []struct {
		Name, Summary string
		Ledger        []LedgerEntry
		Text          string
		Kept          []string
		Refenced      []string
		Leaked        []Leak
		Dropped       []Problem
	}
}

func load(t *testing.T) fixtures {
	t.Helper()
	b, err := os.ReadFile("../../testdata/fixtures.json")
	if err != nil {
		t.Fatal(err)
	}
	var f fixtures
	if err := json.Unmarshal(b, &f); err != nil {
		t.Fatal(err)
	}
	return f
}

func TestWrapMatchesTypeScript(t *testing.T) {
	for _, c := range load(t).Wrap {
		w := Wrap(c.Input, c.Source)
		if w.Text != c.Text || w.Content != c.Content {
			t.Errorf("%s: wrapped text differs\n got: %q\nwant: %q", c.Name, w.Text, c.Text)
		}
		if w.Hash != c.Hash || w.Disarmed != c.Disarmed || w.Invisible != c.Invisible {
			t.Errorf("%s: hash/disarmed/invisible differ: %s/%d/%d vs %s/%d/%d", c.Name, w.Hash, w.Disarmed, w.Invisible, c.Hash, c.Disarmed, c.Invisible)
		}
	}
}

func TestVerifyMatchesTypeScript(t *testing.T) {
	for _, c := range load(t).Verify {
		r := Verify(c.Text)
		if r.OK != c.OK {
			t.Errorf("%s: ok %v, want %v", c.Name, r.OK, c.OK)
		}
		if len(r.Blocks) != len(c.Blocks) {
			t.Fatalf("%s: %d blocks, want %d", c.Name, len(r.Blocks), len(c.Blocks))
		}
		for i, b := range r.Blocks {
			w := c.Blocks[i]
			if string(b.Kind) != w.Kind || b.Hash != w.Hash || b.Start != w.Start || b.End != w.End {
				t.Errorf("%s: block %d differs: %+v vs %+v", c.Name, i, b, w)
			}
		}
		if !reflect.DeepEqual(nonNil(r.Problems), nonNil(c.Problems)) {
			t.Errorf("%s: problems differ:\n got: %+v\nwant: %+v", c.Name, r.Problems, c.Problems)
		}
	}
}

func TestUpgradeMatchesTypeScript(t *testing.T) {
	for _, c := range load(t).Upgrade {
		u := UnwrapKnown(c.Text)
		if (u == nil) != (c.Result == nil) {
			t.Fatalf("%s: nil-ness differs", c.Name)
		}
		if u == nil {
			continue
		}
		if string(u.Vendor) != c.Result.Vendor || u.Description != c.Result.Description || u.Inner != c.Result.Inner {
			t.Errorf("%s: %+v vs %+v", c.Name, *u, *c.Result)
		}
	}
}

func TestScrubMatchesTypeScript(t *testing.T) {
	for _, c := range load(t).Scrub {
		s := ScrubSummary(c.Summary, c.Ledger)
		if s.Text != c.Text {
			t.Errorf("%s: text differs\n got: %q\nwant: %q", c.Name, s.Text, c.Text)
		}
		if !reflect.DeepEqual(nonNilS(s.Kept), nonNilS(c.Kept)) || !reflect.DeepEqual(nonNilS(s.Refenced), nonNilS(c.Refenced)) {
			t.Errorf("%s: kept/refenced differ: %v/%v vs %v/%v", c.Name, s.Kept, s.Refenced, c.Kept, c.Refenced)
		}
		if len(s.Leaked) != len(c.Leaked) {
			t.Fatalf("%s: %d leaks, want %d", c.Name, len(s.Leaked), len(c.Leaked))
		}
		for i := range s.Leaked {
			if s.Leaked[i].Hash != c.Leaked[i].Hash || !reflect.DeepEqual(s.Leaked[i].Lines, c.Leaked[i].Lines) {
				t.Errorf("%s: leak %d differs: %+v vs %+v", c.Name, i, s.Leaked[i], c.Leaked[i])
			}
		}
		if !reflect.DeepEqual(nonNil(s.Dropped), nonNil(c.Dropped)) {
			t.Errorf("%s: dropped differ: %+v vs %+v", c.Name, s.Dropped, c.Dropped)
		}
	}
}

func nonNil(p []Problem) []Problem {
	if p == nil {
		return []Problem{}
	}
	return p
}

func nonNilS(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}
